<script setup lang="ts">
import { ref } from 'vue';
import { m1Api, type Operations } from '../api';
import { beijingDate } from '../search';
import { errorMessage } from '../../../shared/api/client';
import RequestState from '../../../shared/components/RequestState.vue';
const startDate = ref(beijingDate()); const endDate = ref(beijingDate()); const loading = ref(false); const error = ref(''); const data = ref<Operations | null>(null);
async function load() { error.value = ''; data.value = null; if (endDate.value < startDate.value) { error.value = '结束日期不能早于开始日期。'; return; } loading.value = true; try { const startsAt = new Date(`${startDate.value}T00:00:00+08:00`).toISOString(); const endsAt = new Date(Date.parse(`${endDate.value}T00:00:00+08:00`) + 86_400_000).toISOString(); data.value = await m1Api.operations(startsAt, endsAt); } catch (cause) { error.value = errorMessage(cause); } finally { loading.value = false; } }
const metrics = [{ key: 'reservations', label: '预约总数' }, { key: 'checkedIn', label: '已签到' }, { key: 'cancelled', label: '已取消' }, { key: 'noShows', label: '失约' }, { key: 'reservedHours', label: '预约小时数' }] as const;
</script>
<template><div><header class="feature-header"><p class="ui-eyebrow">SPACE OPERATIONS</p><h1>空间使用统计</h1><p>按北京时间日期查询房间与座位的使用情况。</p></header><form class="feature-panel ui-panel" @submit.prevent="load"><div class="feature-grid"><label class="feature-field">开始日期<input v-model="startDate" type="date" required /></label><label class="feature-field">结束日期（包含当天）<input v-model="endDate" type="date" required /></label></div><div class="feature-actions"><button class="ui-button ui-button--primary" :disabled="loading">查询统计</button></div></form><RequestState :loading="loading" :error="error" @retry="load" /><template v-if="data && !loading"><div class="feature-metrics"><div v-for="metric in metrics" :key="metric.key" class="feature-metric ui-panel"><strong>{{ data.totals[metric.key] }}</strong><span>{{ metric.label }}</span></div></div><RequestState :empty="!data.rooms.length" empty-text="该时段暂无使用记录" /><section v-for="room in data.rooms" :key="room.roomId" class="feature-panel ui-panel"><div class="feature-row"><h2>{{ room.roomName }}</h2><RouterLink :to="`/m1/rooms/${room.roomId}/provenance`" class="ui-link">查看状态来源</RouterLink></div><div class="feature-table-wrap"><table class="feature-table"><caption>各座位使用情况</caption><thead><tr><th scope="col">座位</th><th v-for="metric in metrics" :key="metric.key" scope="col">{{ metric.label }}</th></tr></thead><tbody><tr v-for="seat in room.seats" :key="seat.seatId"><th scope="row">{{ seat.seatNumber }}</th><td v-for="metric in metrics" :key="metric.key">{{ seat[metric.key] }}</td></tr><tr><th scope="row">房间合计</th><td v-for="metric in metrics" :key="metric.key">{{ room[metric.key] }}</td></tr></tbody></table></div></section></template></div></template>
<style scoped src="../../../shared/styles/feature.css"></style>
